import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    good_str = input_data[0]
    pattern = input_data[1]
    n = int(input_data[2])
    queries = input_data[3:]

    good_set = set(good_str)

    star_idx = -1
    for i, c in enumerate(pattern):
        if c == '*':
            star_idx = i
            break

    results = []

    for q in queries:
        q_len = len(q)
        p_len = len(pattern)

        if star_idx == -1:
            if q_len != p_len:
                results.append("NO")
                continue

            match = True
            for i in range(p_len):
                pc = pattern[i]
                qc = q[i]
                if pc == '?':
                    if qc not in good_set:
                        match = False
                        break
                elif pc == '*':
                    pass
                else:
                    if pc != qc:
                        match = False
                        break

            results.append("YES" if match else "NO")
        else:
            prefix_len = star_idx
            suffix_len = p_len - star_idx - 1

            if q_len < prefix_len + suffix_len:
                results.append("NO")
                continue

            match_prefix = True
            for i in range(prefix_len):
                pc = pattern[i]
                qc = q[i + 0]
                if pc == '?':
                    if qc not in good Set:
                        match_prefix = False
                        break
                elif pc == '*':
                    pass # Should not happen in prefix part before star
                else:
                    if pc != qc:
                        match_prefix = False
                        break

            if not match_prefix:
                results.append("NO")
                continue

            match_suffix = True
            for i in range(suffix_len):
                pc = pattern[star_idx + 1 + i]
                qc = q[q_len - suffix_len + i]
                if pc == '?':
                    if qc not in good_str:
                        match_suffix = False
                        break
                elif pc == '*':
                    pass 
                else:
                    if pc != qc:
                        match_suffix = False
                        break

            if not match_suffix:
                results.append("NO")
                continue

            middle_start = prefix_len
            middle_end = q_len - suffix_len

            for i in range(middle_start, middle_end):
                if q[i] in good_set:
                    results.append("NO")
                    break
            else:
                results.append("YES")

    for res in results:
        print(res)

if __name__ == "__main__":
    solve()
